export function reviewedRootSelectedCompilerCapability(source,bytes,tree,factory) {
 const recipe=reviewedRootSelectedCompilerRecipe;
 const fail=detail=>assert.fail(`DOCUMENTATION_TOOL_GRAPH_UNQUALIFIED: ${source}; root compiler custody: ${detail}`);
 if(source!==recipe.source||syntaxSha256(bytes)!==recipe.sourceSha256||tree.parseDiagnostics.length)fail('source identity/syntax');
 for(const syntax of [recipe.factoryImport,recipe.pathImport])if(tree.statements.filter(statement=>statement.getText(tree)===syntax).length!==1)fail('named lexical import');
 let owner=factory.parent;while(owner&&!ts.isFunctionDeclaration(owner))owner=owner.parent;
 const selected=recipe.owners[owner?.name?.text];
 if(!selected||syntaxSha256(owner.getText(tree))!==selected.ownerSyntaxSha256)fail('owner/body/root flow');
 if(!ts.isCallExpression(factory)||!ts.isIdentifier(factory.expression)||factory.expression.text!=='createRequire'||factory.arguments.length!==1||factory.getText(tree)!==selected.factorySyntax||syntaxSha256(factory.getText(tree))!==selected.factorySha256)fail('exact factory');
 const declaration=factory.parent,list=declaration?.parent,statement=list?.parent;
 if(!ts.isVariableDeclaration(declaration)||!ts.isIdentifier(declaration.name)||declaration.name.text!=='require'||declaration.initializer!==factory||!ts.isVariableDeclarationList(list)||!(list.flags&ts.NodeFlags.Const)||list.declarations.length!==1||statement.parent!==owner.body)fail('same-block const require');
 const references=[];let factories=0;
 function visit(node){
  if(ts.isIdentifier(node)&&node.text==='require')references.push(node);
  if(ts.isIdentifier(node)&&node.text==='createRequire')factories++;
  ts.forEachChild(node,visit);
 }
 visit(owner);
 if(factories!==1||references.length!==2||references[0]!==declaration.name)fail('alias/shadow/write/escape');
 const consumer=references[1].parent;
 if(!ts.isCallExpression(consumer)||consumer.expression!==references[1]||consumer.arguments.length!==1||!ts.isStringLiteral(consumer.arguments[0])||consumer.arguments[0].text!=='typescript'||consumer.getText(tree)!==selected.consumerSyntax||syntaxSha256(consumer.getText(tree))!==selected.consumerSha256)fail('exact consumer');
 const tsDeclaration=consumer.parent,tsList=tsDeclaration?.parent;
 if(!ts.isVariableDeclaration(tsDeclaration)||!ts.isIdentifier(tsDeclaration.name)||tsDeclaration.name.text!=='ts'||!ts.isVariableDeclarationList(tsList)||!(tsList.flags&ts.NodeFlags.Const)||tsList.declarations.length!==1||tsList.parent.parent!==owner.body||consumer.pos<=factory.end)fail('compiler result use');
 return frozenRecipes({kind:'root-selected-compiler-require',source,sourceSha256:recipe.sourceSha256,owner:owner.name.text,ownerSyntaxSha256:selected.ownerSyntaxSha256,factorySha256:selected.factorySha256,consumerSha256:selected.consumerSha256,baseRelative:'package.json',specifier:'typescript',targetRelative:recipe.foundation.target,version:recipe.foundation.version,profile:selected.profile,profileIdentity:recipe.profiles[selected.profile],nativeFoundationIdentity:recipe.foundation.nativeFoundationIdentity,rootInput:{kind:'symbolic-caller-selected-root',requiresCanonicalDynamicInput:true},runtimeAcquisitionAuthorized:false});
}
function assertRootCompilerPackageMembership(members,directories) {
 const expected=reviewedRootSelectedCompilerRecipe.foundation;
 assert.equal(JSON.stringify([...members].sort((a,b)=>a.path.localeCompare(b.path))),JSON.stringify([...expected.members].sort((a,b)=>a.path.localeCompare(b.path))),'DOCUMENTATION_TOOL_GRAPH_UNQUALIFIED: finite compiler package membership');
 assert.equal(JSON.stringify([...directories].sort()),JSON.stringify([...expected.directories].sort()),'DOCUMENTATION_TOOL_GRAPH_UNQUALIFIED: finite compiler directory membership');
}
function assertRootCompilerPackageDefinition(definition) {
 assert(definition.version==='5.9.3'&&definition.main==='./lib/typescript.js'&&definition.type===undefined&&definition.exports===undefined&&definition.imports===undefined,'DOCUMENTATION_TOOL_GRAPH_UNQUALIFIED: compiler package resolution fields');
}
export function rootSelectedCompilerTarget(root,capability,recordDependency=()=>{}) {
 const recipe=reviewedRootSelectedCompilerRecipe,fail=detail=>assert.fail(`DOCUMENTATION_TOOL_GRAPH_UNQUALIFIED: root compiler resolution: ${detail}`);
 if(!isRootSelectedCompilerCapability(capability)||capability.source!==recipe.source||capability.sourceSha256!==recipe.sourceSha256||capability.baseRelative!=='package.json'||capability.specifier!=='typescript'||capability.targetRelative!==recipe.foundation.target||capability.version!=='5.9.3'||capability.runtimeAcquisitionAuthorized!==false||JSON.stringify(capability.nativeFoundationIdentity)!==JSON.stringify(recipe.foundation.nativeFoundationIdentity))fail('capability identity/base/target');
 const selected=recipe.owners[capability.owner];
 if(!selected||selected.ownerSyntaxSha256!==capability.ownerSyntaxSha256||selected.factorySha256!==capability.factorySha256||selected.consumerSha256!==capability.consumerSha256||selected.profile!==capability.profile||JSON.stringify(recipe.profiles[selected.profile])!==JSON.stringify(capability.profileIdentity)||capability.rootInput?.kind!=='symbolic-caller-selected-root'||capability.rootInput.requiresCanonicalDynamicInput!==true)fail('owner/profile');
 if(typeof root!=='string'||!path.isAbsolute(root)||root!==path.resolve(root)||!([recipe.canonicalDependencyRoot,reviewedIsolatedCompilerInput.root,reviewedRecoveryCompilerInput.root].includes(root))||fs.realpathSync(root)!==root)fail('canonical dependency root');
 const foundationInputFacts=new Map();
 const recordFact=fact=>{recordDependency(fact.path);foundationInputFacts.set(fact.path,fact);};
 const fileFact=selected=>{
  const file=path.join(root,selected);
  if(fs.realpathSync(file)!==file||!fs.lstatSync(file).isFile())fail(`physical target ${selected}`);
  const sha256=syntaxSha256(fs.readFileSync(file));
  recordFact({path:selected,kind:'file',canonical:file,sha256});return sha256;
 };
 const selectedInput=root===reviewedRecoveryCompilerInput.root?reviewedRecoveryCompilerInput:root===reviewedIsolatedCompilerInput.root?reviewedIsolatedCompilerInput:recipe.foundation;
 for(const absent of selectedInput.absent??[]){
  const file=path.join(root,absent);let present=false;
  try{fs.lstatSync(file);present=true;}catch(error){if(error.code!=='ENOENT')throw error;}
  if(present)fail(`unexpected input metadata ${absent}`);
  recordFact({path:absent,kind:'absent',canonical:null});
 }
 for(const pin of selectedInput.pins)if(fileFact(pin.path)!==pin.sha256)fail(`foundation bytes ${pin.path}`);
 const members=[],directories=[];
 function walk(selected){
  const file=path.join(root,selected);
  if(fs.realpathSync(file)!==file||fs.lstatSync(file).isSymbolicLink()||!fs.lstatSync(file).isDirectory())fail(`package directory ${selected}`);
  directories.push(selected);
  const entries=fs.readdirSync(file,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name));
  recordFact({path:selected,kind:'directory',canonical:file,members:entries.map(entry=>({name:entry.name,kind:entry.isDirectory()?'directory':entry.isFile()?'file':'unqualified'}))});
  for(const entry of entries){
   const child=selected+'/'+entry.name;if(entry.isSymbolicLink())fail('package symlink');
   if(entry.isDirectory())walk(child);else if(entry.isFile())members.push({path:child,sha256:fileFact(child)});else fail('package special file');
  }
 }
 walk('node_modules/typescript');
 assertRootCompilerPackageMembership(members,directories);
 for(const absent of recipe.foundation.absent){
  const file=path.join(root,absent);let present=false;
  try{fs.lstatSync(file);present=true;}catch(error){if(error.code!=='ENOENT')throw error;}
  if(present)fail('new package boundary');
  recordFact({path:absent,kind:'absent',canonical:null});
 }
 const definition=JSON.parse(fs.readFileSync(path.join(root,'node_modules/typescript/package.json'),'utf8'));
 assertRootCompilerPackageDefinition(definition);
 return frozenRecipes({...capability,kind:'installedFoundationDependency',inputClass:'source-owned-installed-compiler-foundation',foundationInputFacts:[...foundationInputFacts.values()].sort((a,b)=>a.path.localeCompare(b.path)),capabilityKind:capability.kind,baseFilename:path.join(root,'package.json'),canonicalDependencyRoot:root,canonicalTarget:path.join(root,recipe.foundation.target),sourceImportMetaBase:path.join(root,capability.source),resolution:'exact-root-package-json-CJS-installed-main',packageMembershipSha256:syntaxSha256(JSON.stringify(recipe.foundation.members)),conditionalRuntimeInput:true,runtimeAcquisitionAuthorized:false});
}
export function reviewedSdkGeneratorImport(source,bytes,tree) {
 if(source!==reviewedSdkGeneratorRecipe.source)return null;
 const recipe=reviewedSdkGeneratorRecipe,fail=detail=>assert.fail(`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; SDK importer ${detail}`);
 if(syntaxSha256(bytes)!==recipe.sourceSha256||tree.parseDiagnostics.length)fail('source/syntax changed');
 const imports=tree.statements.filter(statement=>ts.isImportDeclaration(statement)&&statement.getText(tree)===recipe.importSyntax);
 if(imports.length!==1||syntaxSha256(imports[0].getText(tree))!==recipe.importSha256)fail('exact import');
 const owners=tree.statements.filter(statement=>ts.isFunctionDeclaration(statement)&&statement.name?.text===recipe.owner);
 if(owners.length!==1||syntaxSha256(owners[0].getText(tree))!==recipe.ownerSyntaxSha256)fail('caller/body/root/revision/result slots');
 const calls=[];function visit(node){if(ts.isCallExpression(node)&&node.expression.getText(tree)==='generateSdkReference')calls.push(node);ts.forEachChild(node,visit);}visit(tree);
 if(calls.length!==1||calls[0].getText(tree)!==recipe.callSyntax||syntaxSha256(calls[0].getText(tree))!==recipe.callSha256)fail('exact call');
 let owner=calls[0].parent;while(owner&&!ts.isFunctionDeclaration(owner))owner=owner.parent;if(owner!==owners[0])fail('call owner');
 return frozenRecipes({...recipe,sourcePurposeOnly:true,runtimeExecutionAuthorized:false,existingSelectorRenewalAuthorized:false});
}

