export function documentationChildSourceAuthority(root,source){
 const bytes=fs.readFileSync(path.join(root,source),'utf8'),tree=ts.createSourceFile(source,bytes,ts.ScriptTarget.Latest,true),paths=new Set(),names=new Set(['spawnSync','spawn','execFileSync','execFile','execSync','exec']);
 for(const statement of tree.statements)if(ts.isImportDeclaration(statement)&&['node:child_process','child_process'].includes(statement.moduleSpecifier.text)){
  if(statement.importClause?.namedBindings&&ts.isNamedImports(statement.importClause.namedBindings))for(const item of statement.importClause.namedBindings.elements)names.add(item.name.text);
  if(statement.importClause?.namedBindings&&ts.isNamespaceImport(statement.importClause.namedBindings))for(const name of ['spawnSync','spawn','execFileSync','execFile','execSync','exec'])names.add(statement.importClause.namedBindings.name.text+'.'+name);
 }
 const sourceFile=value=>/\.(?:[cm]?js|[cm]?ts|py|go|sh)$/u.test(value);
 function candidate(value,relative=false){if(!sourceFile(value))return;const selected=relative?path.posix.normalize(path.posix.join(path.posix.dirname(source),value)):path.posix.normalize(value);assert(!path.isAbsolute(selected)&&!selected.startsWith('../'),`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; child/source acquisition escapes repository: ${value}`);paths.add(selected);}
 function visit(node){
  if(ts.isNewExpression(node)&&node.expression.getText(tree)==='URL'&&ts.isStringLiteralLike(node.arguments?.[0])&&node.arguments?.[1]?.getText(tree)==='import.meta.url')candidate(node.arguments[0].text,true);
  if(ts.isCallExpression(node)&&names.has(node.expression.getText(tree))){
   function argumentsIn(child){
    if(ts.isStringLiteralLike(child)&&child.text.includes('/')&&sourceFile(child.text))candidate(child.text,child.text.startsWith('.'));
    if(ts.isCallExpression(child)&&['path.join','path.resolve'].includes(child.expression.getText(tree))&&child.arguments[0]?.getText(tree)==='root'&&child.arguments.slice(1).every(ts.isStringLiteralLike))candidate(child.arguments.slice(1).map(argument=>argument.text).join('/'));
    ts.forEachChild(child,argumentsIn);
   }
   for(const argument of node.arguments)argumentsIn(argument);
  }
  ts.forEachChild(node,visit);
 }
 assertReviewedVariableDocumentationChild(source,bytes,tree,candidate);
 visit(tree);return [...paths].sort().map(selected=>{const file=path.join(root,selected);if(!fs.existsSync(file))return {path:selected,canonical:null,sha256:null};const canonical=path.relative(root,fs.realpathSync(file)).replaceAll(path.sep,'/');assert(!canonical.startsWith('../')&&!path.isAbsolute(canonical)&&fs.statSync(file).isFile(),`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; child/source authority escapes repository: ${selected}`);return {path:selected,canonical,sha256:createHash('sha256').update(fs.readFileSync(file)).digest('hex')};});
}

function qualifiedStaticForwarding(root,source,staticSources,seen=new Set()){
 if(staticSources.has(source))return true;if(seen.has(source))return false;seen=new Set([...seen,source]);
 const tree=ts.createSourceFile(source,fs.readFileSync(path.join(root,source),'utf8'),ts.ScriptTarget.Latest,true),bindings=new Set();let forwarded=false;
 for(const statement of tree.statements){
  if(ts.isImportDeclaration(statement)&&statement.importClause?.namedBindings&&ts.isNamedImports(statement.importClause.namedBindings)&&ts.isStringLiteralLike(statement.moduleSpecifier)&&statement.moduleSpecifier.text.startsWith('.')){
   const target=path.posix.normalize(path.posix.join(path.posix.dirname(source),statement.moduleSpecifier.text));if(!fs.existsSync(path.join(root,target))||!qualifiedStaticForwarding(root,target,staticSources,seen))return false;
   for(const item of statement.importClause.namedBindings.elements)bindings.add(item.name.text);continue;
  }
  if(ts.isVariableStatement(statement)&&(statement.declarationList.flags&ts.NodeFlags.Const)){for(const item of statement.declarationList.declarations){if(!ts.isIdentifier(item.name)||!item.initializer||!ts.isIdentifier(item.initializer)||!bindings.has(item.initializer.text))return false;bindings.add(item.name.text);if(statement.modifiers?.some(modifier=>modifier.kind===ts.SyntaxKind.ExportKeyword))forwarded=true;}continue;}
  if(ts.isExportDeclaration(statement)&&!statement.moduleSpecifier&&statement.exportClause&&ts.isNamedExports(statement.exportClause)&&statement.exportClause.elements.every(item=>bindings.has(item.propertyName?.text??item.name.text))){forwarded=true;continue;}
  return false;
 }
 return forwarded;
}
export function assertDocumentationExecutableRole(root,source,staticSources=new Set()){
 const bytes=fs.readFileSync(path.join(root,source),'utf8');
 if(reuseCustody(root,source,bytes))return;
 if(/\.(?:py|go)$/u.test(source)){
  const recipe=documentationExecutableRoleRecipes[source];
  assert(recipe?.role==='documentation-parser-adapter'&&recipe.consumer,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; native documentation consumer has no Source-owned recipe`);
  const command=source.endsWith('.py')?'python3':process.env.KUBECLAW_DOCS_GO_BINARY??'go';
  const argv=source.endsWith('.py')?[new URL('./docs-api-python-ast-v1.py',import.meta.url).pathname,'--stdin-custody',source]:['run',new URL('./docs-api-go-output-role-adapter.go',import.meta.url).pathname,'--documentation-custody',path.join(root,source)];
  const receipt=spawnSync(command,argv,{input:source.endsWith('.py')?bytes:undefined,encoding:'utf8',maxBuffer:32*1024*1024});
  assert.equal(receipt.status,0,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; native custody parse: ${receipt.error?.message??receipt.stderr}`);
  assert.deepEqual(documentationNativeReceipt(JSON.parse(receipt.stdout)),recipe.receipt,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; native executable/import/initialization operations changed`);retainCustody(root,source,bytes,[path.join(root,source),new URL('./docs-api-python-ast-v1.py',import.meta.url).pathname,new URL('./docs-api-go-output-role-adapter.go',import.meta.url).pathname]);return;
 }
 assert(/\.[cm]?js$/u.test(source),`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; unsupported excluded executable class`);
 const selectors=documentationExecutableSelectors(source,bytes,root),recipe=documentationExecutableRoleRecipes[source];
 if(qualifiedStaticForwarding(root,source,staticSources))return; // Exact reviewed static-data forwarding, never executable or object constructors.
 assert(recipe&&recipe.role==='documentation-consumer'&&recipe.consumer&&recipe.authorityInputs,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; no Source-owned executable consumer recipe`);
 assert.deepEqual(documentationSelectorReceipt(selectors),recipe.selectors,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; executable operation inventory changed`);
 const facts=deriveNativeOperationFacts(root,source,selectors,{trustAnchorSources:[anchorSource]});
 assert(facts&&nativeOperationFactDigest(facts)===recipe.factsDigest,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; selected producer/helper/initialization custody changed`);
 assert.deepEqual(documentationChildSourceAuthority(root,source),recipe.authorityInputs,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; literal child/source acquisition authority changed`);
 retainCustody(root,source,bytes,[...facts.map(fact=>path.join(root,fact.source)),...recipe.authorityInputs.map(input=>path.join(root,input.path))]);
}

